/bin/bash -c "python3 - <<'PY'
import json, re, sqlite3
p=json.load(open('packet.json'))
c=sqlite3.connect('file:database.sqlite?mode=ro',uri=True)
for i,x in enumerate(p['items']):
 q=x['question']
 if q.startswith('Which Rel-'):
  match=re.search(r'Which (Rel-\\d+) change requests that modify clause (\\S+) of TS (\\S+) have',q)
  print(i,x['id'],'section',match.groups() if match else 'UNPARSED')
 elif q.startswith('TSG RAN'):
  print(i,x['id'],'pack',re.search(r'RP-\\d+',q).group())
 elif q.startswith('RAN4 recorded'):
  print(i,x['id'],'revision',re.search(r'R4-\\d+',q).group())
 else:
  match=re.search(r'R4-\\d+',q)
  fields=re.search(r'\\(CR (\\S+) to TS (["'^)]+)'"\\)',q)
  row=c.execute('SELECT number,cr_number,spec,doc_type FROM document WHERE number=?',(match.group(),)).fetchall()
  if len(row)"'!=1 or row[0][1:3]!=fields.groups(): print('"'METADATA',i,x['id'],fields.groups(),row)
print('done')
PY"

